function throttle(fn, wait) {
  let last = 0;
  let timer = null;
  let lastArgs;

  return function (...args) {
    const remaining = wait - (Date.now() - last);
    lastArgs = args;

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = Date.now();
      fn.apply(this, lastArgs);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, lastArgs);
      }, remaining);
    }
  };
}

function onScroll() {
  console.log(window.scrollY);
}

window.addEventListener('scroll', throttle(onScroll, 200), { passive: true });
```

Runs on first event, then at most once per 200 ms. Trailing call fires after scrolling stops, so the final position is not missed.

