const express = require('express');
const { Pool } = require('pg');

const pool = new Pool();
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');
}

function decodeCursor(cursor) {
  const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
  if (typeof ts !== 'string' || !/^\d+$/.test(String(id))) {
    throw new Error('Invalid cursor');
  }
  return [ts, String(id)];
}

router.get('/orders', async (req, res, next) => {
  let limit = DEFAULT_LIMIT;
  if (req.query.limit !== undefined) {
    limit = Number(req.query.limit);
    if (!Number.isInteger(limit) || limit < 1) {
      return res.status(400).json({ error: 'limit must be a positive integer' });
    }
    limit = Math.min(limit, MAX_LIMIT);
  }

  let cursor = null;
  if (req.query.cursor !== undefined) {
    try {
      cursor = decodeCursor(req.query.cursor);
    } catch {
      return res.status(400).json({ error: 'Invalid cursor' });
    }
  }

  try {
    // Fetch one extra row to know whether another page exists.
    const { rows } = cursor
      ? await pool.query(
          `SELECT *, created_at::text AS cursor_ts
             FROM orders
            WHERE (created_at, id) < ($1::timestamptz, $2::bigint)
            ORDER BY created_at DESC, id DESC
            LIMIT $3`,
          [cursor[0], cursor[1], limit + 1]
        )
      : await pool.query(
          `SELECT *, created_at::text AS cursor_ts
             FROM orders
            ORDER BY created_at DESC, id DESC
            LIMIT $1`,
          [limit + 1]
        );

    const page = rows.slice(0, limit);
    const nextCursor = rows.length > limit ? encodeCursor(page[page.length - 1]) : null;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: nextCursor,
    });
  } catch (err) {
    // Malformed or out-of-range timestamp or id inside a tampered cursor.
    if (['22007', '22008', '22003'].includes(err.code)) {
      return res.status(400).json({ error: 'Invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;
```

Index needed for the keyset scan:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

- Request: `GET /orders?limit=20`, then `GET /orders?limit=20&cursor=<next_cursor>`. `next_cursor: null` means last page.
- Cursor uses `created_at::text`, not the JS `Date`. `Date` has millisecond precision and PostgreSQL has microsecond, so a `Date` cursor skips or repeats rows.
- Assumes `id` is `bigint` and `created_at` is `timestamptz`. Change the casts and the id check in `decodeCursor` for `uuid` or `timestamp`.
- Cursor is not signed, so the client can forge any position. Add a `WHERE` filter for the owner if orders are per-user.

```go
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
)

var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, short, usage, def string
	boolPtr                 *bool
	strPtr                  *string
}

type argDef struct {
	name, usage string
	required    bool
}

type Parser struct {
	name, desc string
	flags      []*flagDef
	lookup     map[string]*flagDef
	argDefs    []argDef
	args       []string
}

func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc, lookup: map[string]*flagDef{}}
}

func (p *Parser) add(f *flagDef) {
	p.flags = append(p.flags, f)
	p.lookup["--"+f.name] = f
	if f.short != "" {
		p.lookup["-"+f.short] = f
	}
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.add(&flagDef{name: name, short: short, usage: usage, boolPtr: v})
	return v
}

// String defines a flag that takes a value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	p.add(&flagDef{name: name, short: short, usage: usage, def: def, strPtr: v})
	return v
}

// Arg declares a positional argument for the help text and the required check.
func (p *Parser) Arg(name, usage string, required bool) {
	p.argDefs = append(p.argDefs, argDef{name, usage, required})
}

// Args returns the positional arguments found by Parse.
func (p *Parser) Args() []string { return p.args }

func (p *Parser) Parse(argv []string) error {
	p.args = nil
	for i := 0; i < len(argv); i++ {
		a := argv[i]
		if a == "--" {
			p.args = append(p.args, argv[i+1:]...)
			break
		}
		if len(a) < 2 || a[0] != '-' {
			p.args = append(p.args, a)
			continue
		}

		key, val, hasVal := strings.Cut(a, "=")
		if key == "-h" || key == "--help" {
			return ErrHelp
		}
		f, ok := p.lookup[key]
		if !ok {
			return fmt.Errorf("unknown flag: %s", key)
		}

		if f.boolPtr != nil {
			b := true
			if hasVal {
				var err error
				if b, err = strconv.ParseBool(val); err != nil {
					return fmt.Errorf("invalid boolean for %s: %q", key, val)
				}
			}
			*f.boolPtr = b
			continue
		}

		if !hasVal {
			if i+1 >= len(argv) {
				return fmt.Errorf("flag %s needs a value", key)
			}
			i++
			val = argv[i]
		}
		*f.strPtr = val
	}

	for i, d := range p.argDefs {
		if d.required && i >= len(p.args) {
			return fmt.Errorf("missing argument: %s", d.name)
		}
	}
	return nil
}

func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags]", p.name)
	for _, d := range p.argDefs {
		if d.required {
			fmt.Fprintf(w, " <%s>", d.name)
		} else {
			fmt.Fprintf(w, " [%s]", d.name)
		}
	}
	fmt.Fprintln(w)
	if p.desc != "" {
		fmt.Fprintf(w, "\n%s\n", p.desc)
	}

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.argDefs) > 0 {
		fmt.Fprintln(tw, "\nArguments:")
		for _, d := range p.argDefs {
			fmt.Fprintf(tw, "  %s\t%s\n", d.name, d.usage)
		}
	}
	fmt.Fprintln(tw, "\nFlags:")
	for _, f := range p.flags {
		names := "    --" + f.name
		if f.short != "" {
			names = "-" + f.short + ", --" + f.name
		}
		usage := f.usage
		if f.strPtr != nil {
			names += " <value>"
			if f.def != "" {
				usage += fmt.Sprintf(" (default %q)", f.def)
			}
		}
		fmt.Fprintf(tw, "  %s\t%s\n", names, usage)
	}
	fmt.Fprintf(tw, "  -h, --help\tshow this help\n")
	tw.Flush()
}

func main() {
	p := New("copy", "Copy a file.")
	verbose := p.Bool("verbose", "v", "print progress")
	mode := p.String("mode", "m", "0644", "file mode for the destination")
	p.Arg("src", "source file", true)
	p.Arg("dst", "destination file", true)

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, ErrHelp) {
			p.Usage(os.Stdout)
			return
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		p.Usage(os.Stderr)
		os.Exit(2)
	}

	fmt.Println(*verbose, *mode, p.Args())
}
```

